/**
 * `agent/skills/*`: markdown, packaged, and `defineSkill` skills.
 */
import { readFile } from "node:fs/promises";
import { join, relative } from "node:path";
import { getDefinitionKind } from "../brand.js";
import { parseFrontmatter } from "../frontmatter.js";
import { displayPath, isBlank } from "./context.js";
import { isDirectory, isFile, isModuleFile, moduleStem, sortedEntries, toPosix, walkFiles, } from "./fs.js";
import { importDefault } from "./modules.js";
import { validateName } from "./names.js";
/** Declared frontmatter, else the body's first line, else a generic line. */
export function skillDescription(name, declared, body) {
    return declared ?? deriveSkillDescription(body) ?? `Instructions for the ${name} skill.`;
}
/** A packaged skill's sibling files, keyed by path relative to the skill dir. */
export async function skillFiles(skillDir) {
    const files = {};
    for (const filePath of await walkFiles(skillDir)) {
        const rel = toPosix(relative(skillDir, filePath));
        if (rel !== "SKILL.md") {
            files[rel] = { sourcePath: filePath };
        }
    }
    return files;
}
export async function loadSkills(ctx, skillsDir, onDisable) {
    if (!(await isDirectory(skillsDir))) {
        return [];
    }
    const skills = [];
    for (const entry of await sortedEntries(skillsDir)) {
        const entryPath = join(skillsDir, entry.name);
        if (entry.isDirectory()) {
            const skill = await loadPackagedSkill(ctx, entryPath, entry.name);
            if (skill !== undefined) {
                skills.push(skill);
            }
            continue;
        }
        if (!entry.isFile()) {
            continue;
        }
        if (entry.name.endsWith(".md")) {
            const name = entry.name.slice(0, -".md".length);
            if (!validateName(ctx, "skill", name, entryPath)) {
                continue;
            }
            const { data, body } = parseFrontmatter(await readFile(entryPath, "utf8"));
            skills.push({
                name,
                description: skillDescription(name, data.description, body),
                markdown: body.trim(),
                files: {},
            });
            continue;
        }
        if (isModuleFile(entry.name)) {
            const name = moduleStem(entry.name);
            if (!validateName(ctx, "skill", name, entryPath)) {
                continue;
            }
            const definition = await importDefault(ctx, entryPath, onDisable === undefined ? "skill" : ["skill", "disabled"]);
            if (definition === undefined) {
                continue;
            }
            if (getDefinitionKind(definition) === "disabled") {
                onDisable?.(name, entryPath);
                continue;
            }
            // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the loader already checked this definition brand; importDefault returns unknown
            skills.push(compileSkill(name, definition));
        }
    }
    return skills;
}
/** A skill whose body and sibling files are in memory (`defineSkill`, extensions). */
function compileSkill(name, skill) {
    const files = {};
    for (const [rel, contents] of Object.entries(skill.files ?? {})) {
        files[rel] = { contents };
    }
    return {
        name,
        description: skillDescription(name, skill.description, skill.markdown),
        markdown: skill.markdown.trim(),
        files,
    };
}
async function loadPackagedSkill(ctx, skillDir, name) {
    const skillMdPath = join(skillDir, "SKILL.md");
    if (!(await isFile(skillMdPath))) {
        ctx.diagnostics.push({
            severity: "warning",
            path: displayPath(ctx, skillDir),
            message: "Skill directories must contain a SKILL.md; ignoring.",
        });
        return undefined;
    }
    if (!validateName(ctx, "skill", name, skillDir)) {
        return undefined;
    }
    const { data, body } = parseFrontmatter(await readFile(skillMdPath, "utf8"));
    if (data.description === undefined || isBlank(data.description)) {
        ctx.diagnostics.push({
            severity: "error",
            path: displayPath(ctx, skillMdPath),
            message: "Packaged skills require `description` frontmatter in SKILL.md (there is no filename slug to fall back on).",
        });
        return undefined;
    }
    return {
        name,
        description: data.description,
        markdown: body.trim(),
        files: await skillFiles(skillDir),
    };
}
/**
 * Advertise the first non-empty, non-code-fence line of the body, with any
 * leading `#`, `>`, `*`, or `-` markers stripped.
 */
function deriveSkillDescription(markdown) {
    let inFence = false;
    for (const rawLine of markdown.split(/\r?\n/)) {
        const line = rawLine.trim();
        if (line.startsWith("```")) {
            inFence = !inFence;
            continue;
        }
        if (inFence || line === "") {
            continue;
        }
        const stripped = line.replace(/^[#>*\s-]+/, "").trim();
        if (stripped !== "") {
            return stripped.length > 200 ? `${stripped.slice(0, 197)}...` : stripped;
        }
    }
    return undefined;
}
